        qout("Pass");
        return true;
    } else {
        qout("Fail");
        return false;
    }
}
int main() {
    int _passed = 0;
    int _failed = 0;
    if (_test(1, "Hello, Me", greet("Me"), "greet(\"Me\")")) {
        _passed++;
    } else {
        _failed++;
    }
    if (_test(2, "Hello, World", greet(), "greet()")) {
        _passed++;
    } else {
        _failed++;
    }
    qout("%s", f"\n----------------\n{_passed} Passed, {_failed} Failed.\n");
}

